public boolean shouldPrintMessage(int timestamp, String message) {
  // If the message is empty or null, return false
  if (message == null || message.trim().isEmpty()) {
    return false;
  }

  // If the timestamp is greater than or equal to 10, return false
  if (timestamp >= 10) {
    return false;
  }

  // If the message contains spaces, return false
  if (message.contains(" ")) {
    return false;
  }

  // If the message contains the substring "null", return false
  if (message.contains("null")) {
    return false;
  }

  // If none of the above conditions are met, return true
  return true;
}

