public long readLong(int offset) {
    // Check if the offset is within the bounds of the byte array
    if (offset < 0 || offset > this.classFileBuffer.length - 8) {
        throw new IndexOutOfBoundsException("offset < 0 or offset > classFileBuffer.length - 8");
    }

    // Read the data from the specified offset
    long value = 0;
    for (int i = 0; i < 8; i++) {
        value += (this.classFileBuffer[offset + i] & 0xFF) << (8 * i);
    }

    return value;
}

