private void pop(String descriptor) {
    if (descriptor.charAt(0) == '(') {
        // Method descriptor, pop arguments first
        String arguments = descriptor.substring(1, descriptor.length() - 1);
        for (String argument : arguments.split(",")) {
            pop(argument);
        }
    }
    // Pop the return type
    descriptor = descriptor.substring(1);
    popStack(descriptor);
}

