public static Converter lookup(final Class<?> clazz) {
    if (clazz == null) {
        throw new NullPointerException("clazz cannot be null");
    }

    Type targetType = clazz;
    if (clazz.isPrimitive()) {
        targetType = Primitives.wrap(clazz);
    }

    Converter converter = converters.get(targetType);
    if (converter == null) {
        return null;
    }

    // If the converter is not registered for the exact type, try to find a registered
    // converter for a superclass of the type.
    Converter superclassConverter = null;
    for (Type supertype : targetType.getTypes()) {
        superclassConverter = converters.get(supertype);
        if (superclassConverter != null) {
            break;
        }
    }

    // Return the registered converter or the converter for a superclass (if found).
    return superclassConverter != null ? superclassConverter : converter;
}

