public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {

  // Check whether the input box is not null
  if (box == null) {
    throw new IllegalArgumentException("Box cannot be null");
  }

  // Check whether the input box is an instance of Box2D
  if (!(box instanceof Box2D)) {
    throw new IllegalArgumentException("Box must be an instance of Box2D");
  }

  // Split the input box along the x axis
  float midX = box.getLowerBound().getX() + (box.getUpperBound().getX() - box.getLowerBound().getX()) / 2;
  Box2D leftBox = new Box2D(box.getLowerBound(), new Vector2D(midX, box.getUpperBound().getY()));
  Box2D rightBox = new Box2D(new Vector2D(midX, box.getLowerBound().getY()), box.getUpperBound());

  // Return the two resulting boxes
  return new Pair<Box2D,Box2D>(leftBox, rightBox);
}

