private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {

    // If the index is negative or greater than or equal to the number of octets in the buffer, throw an exception
    if (i < 0 || i >= bb.limit()) {
        throw new IllegalArgumentException("Index out of bounds");
    }

    // If the StringBuffer is null, throw an exception
    if (sb == null) {
        throw new IllegalArgumentException("StringBuilder must not be null");
    }

    // Start from the current position in the buffer
    int index = i;

    // While there are more octets to decode and the buffer has sufficient remaining data
    while (index < bb.limit() && (bb.get(index) & 0x80) != 0) {
        // Get the next octet
        byte octet = bb.get(index);

        // If the octet is not a continuation octet, throw an exception
        if ((octet & 0xC0) != 0x80) {
            throw new IllegalArgumentException("Invalid continuation octet");
        }

        // Add the lower 6 bits of the octet to the StringBuffer
        sb.append((char) (octet & 0x7F));

        // Increment the index
        index++;
    }

    // Return the new index
    return index;
}

