public static Type resolveBound(TypeVariable<?> typeVariable) {

    // check if the type variable is null
    if (typeVariable == null) {
        return Unknown.class;
    }

    // get the bounds of the type variable
    Type[] bounds = typeVariable.getBounds();

    // check if the bounds are null or empty
    if (bounds == null || bounds.length == 0) {
        return Unknown.class;
    }

    // loop through the bounds and return the first non-null bound
    for (Type bound : bounds) {
        if (bound != null) {
            return bound;
        }
    }

    // if the bounds are all null, return Unknown.class
    return Unknown.class;
}

