public static void selectRow(int row, JTable table, JScrollPane pane) {
    // Check if the row is within the bounds of the table
    if (row >= 0 && row < table.getRowCount()) {
        // Translate the given row into a view row index
        int viewRow = table.convertRowIndexToView(row);
        // Select the row and scroll to its position
        table.setRowSelectionInterval(viewRow, viewRow);
        pane.getVerticalScrollBar().setValue(viewRow);
        // Repaint the table to paint the newly selected row
        table.repaint();
    } else {
        // Throw an exception if the row is outside the bounds of the table
        throw new IllegalArgumentException("The row index " + row + " is not within the bounds of the table");
    }
}

