public void abbreviate(final String name) {
        final StringBuffer abbreviation = new StringBuffer();
        final char[] nameChars = name.toCharArray();
        int charIndex = 0;
        while (charIndex < nameChars.length) {
            char currentChar = nameChars[charIndex];
            char nextChar = charIndex < nameChars.length - 1 ? nameChars[charIndex + 1] : (char) 0;
            if (!Character.isUpperCase(currentChar)) {
                abbreviation.append(currentChar);
                charIndex++;
            } else {
                if (nextChar != '\'') { // ignoring words like "oa"
                    abbreviation.append(Character.toLowerCase(currentChar));
                }
                charIndex += 2;
            }
        }
        buf.append(abbreviation);
    }

