        throw new IllegalArgumentException("intValue is out of range");
    }
    if (intValue == 0) {
        put((byte)0);
    } else if (intValue > 0) {
        put((byte)1);
        for (int i = 1; i < Integer.BYTES; i++) {
            put((byte)(intValue >> (i * Byte.SIZE)));
        }
    } else {
        put((byte)-1);
        for (int i = 1; i < Integer.BYTES; i++) {
            put((byte)(~(intValue >> (i * Byte.SIZE))));
        }
    }
    return this;
}

