private void pop(String descriptor) {
    switch (descriptor.charAt(0)) {
        case '(':
            // Case when the descriptor describes a method
            // Read the argument types of the method
            String[] argumentTypes = descriptor.substring(1, descriptor.length() - 1).split(";");
            // Pop the arguments from the stack
            for (String argumentType : argumentTypes) {
                pop(argumentType);
            }
            break;
        case 'L':
            // Case when the descriptor describes a type
            // Pop the type from the stack
            pop(descriptor.substring(1));
            break;
        default:
            // Error: invalid descriptor
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
}

