public long readRawVarint64() throws IOException {
    // Initialize a variable to store the result
    long result = 0;

    // Initialize a variable to keep track of the bits read
    int bitsRead = 0;

    // Initialize a variable to store the current byte
    int currentByte;

    // Read the first byte
    currentByte = input.readByte();

    // Check if the byte has the most significant bit set
    if ((currentByte & 0x80) == 0) {
        // If not, this is the only byte we need to read
        result = currentByte;
        bitsRead = 8;
    } else {
        // If so, we need to read more bytes
        result = currentByte & 0x7f;
        bitsRead = 7;

        // Keep reading until we have read all the bytes we need
        while ((currentByte & 0x80) == 0x80) {
            currentByte = input.readByte();
            result = (result << 7) | (currentByte & 0x7f);
            bitsRead += 7;
        }
    }

    // Shift the result to the correct position
    result = result >>> (8 - bitsRead);

    // Return the result
    return result;
}

