    // Attempt to read a field tag, returning zero if we have reached EOF
    // Protocol message parsers use this to read tags, since a protocol message may legally end wherever a tag occurs, and zero is not a valid tag number
    try {
        int tag = inputStream.read();
        if (tag == 0 || tag == -1) {
            return 0;
        }
        return tag;
    } catch (IOException e) {
        throw new IOException("Error reading tag", e);
    }
}

